import{_ as s,o as e,c as n,a0 as p}from"./chunks/framework.BpJS36ta.js";const h=JSON.parse('{"title":"Database","description":"","frontmatter":{},"headers":[],"relativePath":"modules/syntax/database.md","filePath":"modules/syntax/database.md"}'),t={name:"modules/syntax/database.md"};function i(l,a,d,o,r,c){return e(),n("div",null,[...a[0]||(a[0]=[p(`<h1 id="database" tabindex="-1">Database <a class="header-anchor" href="#database" aria-label="Permalink to &quot;Database&quot;">​</a></h1><p>Modul <code>database</code> adalah penyedia koneksi ke driver database: <code>nosql</code>, <code>mariadb</code>, <code>mysql</code>, <code>psql</code>, <code>sqlite</code>. Ditulis murni dengan bahasa Rupa.</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import db from rupa</span></span></code></pre></div><h2 id="registry-driver" tabindex="-1">Registry driver <a class="header-anchor" href="#registry-driver" aria-label="Permalink to &quot;Registry driver&quot;">​</a></h2><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>print(db.driver.list())            // [&quot;nosql&quot;, &quot;mariadb&quot;, &quot;mysql&quot;, &quot;psql&quot;, &quot;sqlite&quot;]</span></span>
<span class="line"><span>print(db.driver.has(&quot;sqlite&quot;))     // true</span></span>
<span class="line"><span>print(db.driver.get(&quot;psql&quot;))       // spec driver: port default, kebutuhan auth</span></span></code></pre></div><h2 id="dsn" tabindex="-1">DSN <a class="header-anchor" href="#dsn" aria-label="Permalink to &quot;DSN&quot;">​</a></h2><p>Bentuk umum DSN:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>scheme://[user[:pass]@]host[:port]/database</span></span></code></pre></div><p>Contoh:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mariadb://admin:secret@db.local:3307/shop</span></span>
<span class="line"><span>psql://user:pass@localhost/app</span></span>
<span class="line"><span>nosql://cluster.local:9200/cache</span></span>
<span class="line"><span>sqlite://data/app.db</span></span>
<span class="line"><span>sqlite:///absolute/path/file.db</span></span></code></pre></div><p>Parser DSN tersedia jika ingin mengurai manual:</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>u = db.dsn.parse(&quot;mariadb://admin:secret@db.local:3307/shop&quot;)</span></span>
<span class="line"><span>print(u.host)   // db.local</span></span>
<span class="line"><span>print(u.port)   // 3307</span></span>
<span class="line"><span>print(u.user)   // admin</span></span>
<span class="line"><span>print(u.path)   // /shop</span></span></code></pre></div><h2 id="membuka-koneksi" tabindex="-1">Membuka koneksi <a class="header-anchor" href="#membuka-koneksi" aria-label="Permalink to &quot;Membuka koneksi&quot;">​</a></h2><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>c = db.open(&quot;mariadb://admin:secret@db.local/shop&quot;)</span></span>
<span class="line"><span>if c.ok:</span></span>
<span class="line"><span>    print(c.driver)     // mariadb</span></span>
<span class="line"><span>    print(c.host)       // db.local</span></span>
<span class="line"><span>    print(c.port)       // 3306 (default dari spec driver)</span></span>
<span class="line"><span>    print(c.database)   // shop</span></span>
<span class="line"><span>    print(c.status)     // ready</span></span>
<span class="line"><span>else:</span></span>
<span class="line"><span>    print(c.error)</span></span></code></pre></div><p>Khusus <code>sqlite</code>, authority + path adalah lokasi file:</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>c = db.open(&quot;sqlite://data/app.db&quot;)</span></span>
<span class="line"><span>print(c.database)  // data/app.db</span></span></code></pre></div><h2 id="validasi" tabindex="-1">Validasi <a class="header-anchor" href="#validasi" aria-label="Permalink to &quot;Validasi&quot;">​</a></h2><p><code>db.open()</code> memvalidasi DSN terhadap spec driver dan mengembalikan object dengan <code>ok: false</code> beserta <code>error</code> bila tidak valid — tidak pernah melempar exception:</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>print(db.open(&quot;oracle://x/y&quot;).error)</span></span>
<span class="line"><span>// unknown driver: oracle</span></span>
<span class="line"><span></span></span>
<span class="line"><span>print(db.open(&quot;mariadb://admin@db.local/shop&quot;).error)</span></span>
<span class="line"><span>// user and password are required</span></span></code></pre></div><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Saat ini <code>db.open()</code> belum melakukan I/O jaringan. Status <code>ready</code> berarti DSN valid dan parameter koneksi lengkap — siap disambungkan ke implementasi driver nyata.</p>`,21)])])}const b=s(t,[["render",i]]);export{h as __pageData,b as default};
